    description:
      "tokenize splits text into lowercase words (letters and apostrophes, case does not matter). countWords counts them, topWords gives the n most common as [word, count] (equal counts in alphabetical order) and averageLength is the mean word length rounded to the nearest tenth.",
    hint: 'Try the word "The", a tie in counts, and an average that ends in .x5.',
    bugCount: 3,
    timeLimitSec: 480,
    basePoints: 300,
    tags: ["strings", "objects", "sorting", "rounding"],
    buggy:
      '// Word statistics for a piece of text.\n// Words are made of letters and apostrophes; everything else separates them.\n// Case does not matter: "The" and "the" are the same word, kept in lowercase.\n\nfunction tokenize(text) {\n  const matches = text.match(/[A-Za-z\']+/g);\n  return matches ?? [];\n}\n\n// Counts how many times each word appears, as an object word -> count.\nfunction countWords(words) {\n  const counts = Object.create(null);\n  for (const word of words) {\n    counts[word] = (counts[word] || 0) + 1;\n  }\n  return counts;\n}\n\n// The `n` most common words as [word, count] pairs, most common first.\n// Words with the same count are in alphabetical order.\nfunction topWords(counts, n) {\n  return Object.entries(counts)\n    .sort((a, b) => b[1] - a[1])\n    .slice(0, n);\n}\n\n// Mean word length rounded to the nearest tenth; 0 when there are no words.\nfunction averageLength(words) {\n  if (words.length === 0) return 0;\n  const letters = words.reduce((sum, word) => sum + word.length, 0);\n  return Math.floor((letters / words.length) * 10) / 10;\n}\n\n// Everything at once.\nfunction summarize(text, n = 3) {\n  const words = tokenize(text);\n  const counts = countWords(words);\n  return {\n    total: words.length,\n    unique: Object.keys(counts).length,\n    top: topWords(counts, n),\n    averageLength: averageLength(words),\n  };\n}\n\n// The words that appear exactly once, in the order they first appear.\nfunction singletons(text) {\n  const words = tokenize(text);\n  const counts = countWords(words);\n  return [...new Set(words)].filter((word) => counts[word] === 1);\n}\n',
    tests:
      'test("splits words and ignores punctuation", () => {\n  expect(tokenize("Hello, world! It\'s 5 o\'clock.")).toEqual([\n    "hello",\n    "world",\n    "it\'s",\n    "o\'clock",\n  ]);\n});\ntest("treats upper and lower case as the same word", () => {\n  const counts = countWords(tokenize("The cat and THE hat"));\n  expect(counts.the).toBe(2);\n});\ntest("counts words that look like object properties", () => {\n  const counts = countWords(tokenize("constructor the constructor"));\n  expect(counts.constructor).toBe(2);\n  expect(counts.the).toBe(1);\n});\ntest("breaks ties alphabetically", () => {\n  const top = topWords(\n    countWords(tokenize("pear apple pear fig apple kiwi")),\n    3,\n  );\n  expect(top).toEqual([\n    ["apple", 2],\n    ["pear", 2],\n    ["fig", 1],\n  ]);\n});\ntest("rounds the average length to the nearest tenth", () => {\n  expect(averageLength(["abcd", "abcde"])).toBe(4.5);\n  expect(averageLength(["abc", "abc", "abc", "abcd"])).toBe(3.3);\n});\ntest("lists the words used only once", () => {\n  expect(singletons("a b a c")).toEqual(["b", "c"]);\n});\n',
